// 原生 CDP + 实际 Vue 组件；所有业务数据来自内存夹具，阻止后端及外网请求。
const { spawn } = require('node:child_process')
const fs = require('node:fs/promises')
const path = require('node:path')
const assert = require('node:assert/strict')
const { parseArgs } = require('node:util')
const { values } = parseArgs({ options: { browser: { type: 'string' }, output: { type: 'string' }, fixture: { type: 'string', default: 'http://127.0.0.1:3060/tests/fixtures/chat-insights.html' } } })
if (!values.browser || !values.output) throw new Error('需要 --browser 与 --output 参数')
const output = path.resolve(values.output), fixtureOrigin = new URL(values.fixture).origin
const pause = ms => new Promise(resolve => setTimeout(resolve, ms))
async function main() {
  await fs.mkdir(output, { recursive: true })
  const profile = await fs.mkdtemp(path.join(output, 'isolated-profile-'))
  const child = spawn(values.browser, ['--headless', '--disable-gpu', '--no-first-run', '--disable-background-networking', '--remote-debugging-port=3061', `--user-data-dir=${profile}`, 'about:blank'], { windowsHide: true, stdio: ['ignore', 'ignore', 'pipe'] })
  let socket, sequence = 0
  const pending = new Map(), result = { mode: 'headless_synthetic_dashboard_real_components', remote_model_calls: 0, checks: [], layouts: {}, blocked_requests: [], errors: [] }
  child.stderr.on('data', data => { result.browser_stderr = (result.browser_stderr || '') + data.toString() })
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const id = ++sequence
    const timeout = setTimeout(() => { pending.delete(id); reject(new Error(`CDP 请求超时：${method}`)) }, 15000)
    pending.set(id, { resolve, reject, timeout })
    socket.send(JSON.stringify({ id, method, params }))
  })
  try {
    let pages
    for (let i = 0; i < 60; i++) {
      try { pages = await (await fetch('http://127.0.0.1:3061/json/list')).json(); if (pages.some(page => page.type === 'page')) break } catch (err) { if (i === 59) throw err }
      await pause(100)
    }
    socket = new WebSocket(pages.find(page => page.type === 'page').webSocketDebuggerUrl)
    await new Promise((resolve, reject) => { socket.onopen = resolve; socket.onerror = reject })
    socket.onmessage = event => {
      const data = JSON.parse(event.data)
      if (data.id) {
        const waiter = pending.get(data.id)
        if (!waiter) return
        pending.delete(data.id)
        clearTimeout(waiter.timeout)
        if (data.error) waiter.reject(new Error(JSON.stringify(data.error))); else waiter.resolve(data.result)
      }
      if (data.method === 'Runtime.exceptionThrown') result.errors.push(data.params.exceptionDetails.text)
      if (data.method === 'Fetch.requestPaused') {
        const url = new URL(data.params.request.url)
        const blocked = url.origin !== fixtureOrigin || url.pathname.startsWith('/api/')
        if (blocked) result.blocked_requests.push(url.href)
        void send(blocked ? 'Fetch.failRequest' : 'Fetch.continueRequest', { requestId: data.params.requestId, ...(blocked ? { errorReason: 'BlockedByClient' } : {}) }).catch(error => result.errors.push(error.message))
      }
    }
    await send('Page.enable'); await send('Runtime.enable')
    await send('Fetch.enable', { patterns: [{ urlPattern: 'http*', requestStage: 'Request' }] })
    const evaluate = async expression => {
      const data = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
      if (data.exceptionDetails) throw new Error(JSON.stringify(data.exceptionDetails))
      return data.result.value
    }
    const wait = async expression => {
      for (let i = 0; i < 100; i++) { if (await evaluate(expression)) return; await pause(100) }
      throw new Error(`页面条件未满足：${expression}`)
    }
    const click = selector => evaluate(`document.querySelector(${JSON.stringify(selector)}).click()`)
    const setValue = (selector, value) => evaluate(`(() => { const element = document.querySelector(${JSON.stringify(selector)}); element.value = ${JSON.stringify(value)}; element.dispatchEvent(new Event('input', {bubbles:true})); element.dispatchEvent(new Event('change', {bubbles:true})); })()`)
    const viewport = width => send('Emulation.setDeviceMetricsOverride', { width, height: width === 390 ? 844 : 1000, deviceScaleFactor: 1, mobile: width === 390 })
    const capture = async name => {
      const screenshot = await send('Page.captureScreenshot', { format: 'png' })
      await fs.writeFile(path.join(output, `${name}.png`), Buffer.from(screenshot.data, 'base64'))
    }
    const checkLayout = async name => {
      const layout = await evaluate(`(() => {
        const panel=document.querySelector('.chat-insights-panel'), content=document.querySelector('.preview-content'), scroll=document.querySelector('.insights-scroll'), sidebar=document.querySelector('.preview-sessions');
        const p=panel.getBoundingClientRect(), c=content.getBoundingClientRect();
        return {viewport:innerWidth, panelWidth:p.width, contentWidth:c.width, left:p.left, right:p.right, overflow:scroll.scrollWidth-scroll.clientWidth, pageOverflow:document.documentElement.scrollWidth-innerWidth, sidebarVisible:getComputedStyle(sidebar).display!=='none', conversationHidden:getComputedStyle(document.querySelector('.fake-conversation')).display==='none', gridColumns:getComputedStyle(document.querySelector('.portrait-grid')).gridTemplateColumns};
      })()`)
      assert.ok(Math.abs(layout.panelWidth - layout.contentWidth) <= 1, '画像必须占满聊天主区')
      assert.ok(layout.left >= 0 && layout.right <= layout.viewport + 1)
      assert.equal(layout.overflow, 0); assert.equal(layout.pageOverflow, 0)
      assert.equal(layout.conversationHidden, true)
      assert.equal(layout.sidebarVisible, layout.viewport > 680)
      result.layouts[name] = layout
      await capture(name)
      if (['private-dark-1440', 'group-dark-1280', 'private-light-390'].includes(name)) {
        await evaluate("document.querySelector('.topics-card').scrollIntoView({block:'start'})")
        await capture(`${name}-details`)
        await evaluate("document.querySelector('.insights-scroll').scrollTop = 0")
      }
    }
    const outputText = () => evaluate("document.querySelector('.preview-toolbar output').textContent")
    await viewport(1280)
    await send('Page.navigate', { url: values.fixture })
    await wait("document.querySelector('.summary-card')?.textContent.includes('合成小林摘要')")
    assert.equal(await evaluate("document.querySelector('[aria-label=\"画像分析方式\"]').value"), 'laya')
    assert.equal(await evaluate("document.querySelectorAll('.mbti-axis meter').length"), 4)
    assert.equal(await evaluate("document.querySelector('.analysis-settings').open"), false)
    assert.match(await outputText(), /真实模型调用 0.*新建合成任务 0.*API 配置读取 0/)
    for (const selector of ['.insight-overview', '.portrait-hero', '.mbti-card', '.radar-card', '.topics-card', '.summary-card', '.affinity-score']) assert.equal(await evaluate(`Boolean(document.querySelector(${JSON.stringify(selector)}))`), true)
    await checkLayout('private-light-1280')
    await click('[aria-label="预览切换主题"]'); await checkLayout('private-dark-1280')
    await viewport(1440); await checkLayout('private-dark-1440')
    await click('[aria-label="预览切换主题"]'); await checkLayout('private-light-1440')
    await viewport(390); await checkLayout('private-light-390')
    await click('[aria-label="预览切换主题"]'); await checkLayout('private-dark-390')
    result.checks.push('private_full_main_sidebar_and_six_responsive_theme_views')

    await viewport(1280)
    await click('[aria-label="预览切换证据不足"]')
    await wait("!document.querySelector('[data-radar-area]')")
    assert.equal(await evaluate("document.querySelector('[data-mbti-axis=\"JP\"] meter') === null"), true)
    assert.match(await evaluate("document.querySelector('.mbti-card .card-heading').textContent"), /证据不足/)
    await capture('private-unknown-dark')
    await click('[aria-label="预览切换证据不足"]')
    await wait("document.querySelector('[data-radar-area]')")
    result.checks.push('unknown_radar_and_mbti_do_not_invent_scores_or_type')

    await click('[aria-label="画像分析设置"]')
    await wait("document.querySelector('.analysis-settings').open")
    assert.match(await evaluate("document.querySelector('.local-model').textContent"), /已就绪/)
    assert.equal(await evaluate("document.querySelector('.start-analysis').disabled"), false)
    await setValue('[aria-label="画像分析历史"]', 'saved-private-older')
    await wait("document.querySelector('[aria-label=\"画像分析历史\"]').value === 'saved-private-older'")
    await click('[aria-label="预览模拟任务失败"]')
    await wait("document.querySelector('.insight-overview').textContent.includes('分析失败')")
    assert.match(await evaluate("document.querySelector('.insights-scroll').textContent"), /SYNTHETIC_FAILURE.*synthetic-diag-001/s)
    assert.equal(await evaluate("Boolean(document.querySelector('.summary-card .summary-quote'))"), true)
    await capture('settings-failure-dark')
    await click('[aria-label="预览模拟任务失败"]')
    await click('[aria-label="预览模拟模型缺失"]')
    await wait("document.querySelector('.local-model').textContent.includes('尚未下载')")
    assert.equal(await evaluate("document.querySelector('.start-analysis').disabled"), true)
    await click('[aria-label="下载本地画像模型"]')
    await wait("document.querySelector('[aria-label=\"暂停本地模型下载\"]')")
    await click('[aria-label="暂停本地模型下载"]')
    await wait("document.querySelector('.local-model').textContent.includes('已暂停')")
    await click('.local-import summary')
    await setValue('[aria-label="已有画像模型目录"]', 'synthetic-local-directory')
    await click('[aria-label="导入已有画像模型"]')
    await wait("document.querySelector('.local-model').textContent.includes('已就绪')")
    assert.match(await outputText(), /新建合成任务 0.*API 配置读取 0/)
    await click('[aria-label="显示消息情绪与意图标签"]')
    await wait("document.querySelectorAll('.message-insight-label').length === 2")
    await click('[aria-label="返回聊天"]')
    await wait("!document.querySelector('.chat-insights-panel')")
    assert.equal(await evaluate("getComputedStyle(document.querySelector('.fake-conversation')).display === 'none'"), false)
    await capture('return-to-chat-with-saved-labels')
    result.checks.push('settings_history_failures_local_readiness_import_and_saved_labels')

    await click('[aria-label="预览打开画像"]')
    await wait("document.querySelector('.summary-card [data-source=\"a\"]')")
    await click('.summary-card [data-source="a"]')
    await wait("!document.querySelector('.chat-insights-panel') && document.querySelector('.located-source')")
    assert.match(await evaluate("document.querySelector('.located-source').textContent"), /synthetic:message:1/)
    assert.equal(await evaluate("getComputedStyle(document.querySelector('.fake-conversation')).display === 'none'"), false)
    result.checks.push('source_navigation_returns_to_chat_and_keeps_message_context')

    await click('[aria-label="预览打开画像"]')
    await wait("document.querySelector('.summary-card')")
    await click('[aria-label="画像分析设置"]')
    await click('[aria-label="移除当前分析记录"]')
    await wait("document.querySelector('.history-confirmation')")
    assert.match(await evaluate("document.querySelector('.history-confirmation').textContent"), /消息标签、画像与原文依据仍保留/)
    await click('[aria-label="取消移除分析历史"]')
    assert.equal(await evaluate("document.querySelectorAll('[aria-label=\"画像分析历史\"] option').length"), 3)
    await click('[aria-label="移除当前分析记录"]')
    await click('button[aria-label="确认移除分析历史"]')
    await wait("document.querySelectorAll('[aria-label=\"画像分析历史\"] option').length === 2")
    assert.equal(await evaluate("Boolean(document.querySelector('.summary-card [data-source=\"a\"]'))"), true)
    assert.equal(await evaluate("document.querySelectorAll('.message-insight-label').length"), 2)
    await click('[aria-label="清空画像分析历史"]')
    await click('button[aria-label="确认移除分析历史"]')
    await wait("document.querySelectorAll('[aria-label=\"画像分析历史\"] option').length === 1")
    await evaluate("document.querySelector('.history').scrollIntoView({block:'start'})")
    await capture('history-cleared-result-retained')
    await click('[aria-label="返回聊天"]')
    await click('[aria-label="预览打开画像"]')
    await wait("document.querySelector('.summary-card [data-source=\"a\"]')")
    await click('[aria-label="画像分析设置"]')
    await click('[aria-label="查看保留画像结果"]')
    await wait("document.querySelectorAll('[aria-label=\"画像分析历史\"] option').length === 3")
    assert.match(await evaluate("document.querySelector('[aria-label=\"画像分析历史\"]').textContent"), /已移除/)
    await setValue('[aria-label="画像分析历史"]', 'saved-private-older')
    await click('.summary-card [data-source="a"]')
    await wait("!document.querySelector('.chat-insights-panel') && document.querySelector('.located-source')")
    assert.match(await outputText(), /新建合成任务 0.*API 配置读取 0/)
    result.checks.push('history_single_and_bulk_removal_keeps_labels_portrait_sources_and_reopens_without_model_calls')

    await click('[aria-label="预览打开画像"]')
    await wait("document.querySelector('.summary-card')")
    await click('[aria-label="预览切换群聊"]')
    await wait("document.querySelector('.summary-card')?.textContent.includes('合成群整体摘要')")
    assert.equal(await evaluate("document.querySelector('.mbti-card') === null && document.querySelector('.affinity-score') === null"), true)
    assert.equal(await evaluate("Boolean(document.querySelector('.group-atmosphere')) && Boolean(document.querySelector('.group-stats'))"), true)
    assert.match(await outputText(), /成员读取 0/)
    await checkLayout('group-dark-1280')
    await viewport(390); await checkLayout('group-dark-390')
    await click('[aria-label="预览切换主题"]'); await checkLayout('group-light-390')
    await viewport(1280); await checkLayout('group-light-1280')
    await click('[aria-label="选择分析对象"]')
    await wait("document.querySelector('[aria-label=\"画像分析对象\"]').options.length === 3")
    await setValue('[aria-label="画像分析对象"]', 'a')
    await wait("document.querySelector('.summary-card')?.textContent.includes('合成成员 a摘要')")
    assert.match(await evaluate("document.querySelector('.analysis-launch .start-analysis').textContent"), /同名成员/)
    assert.match(await evaluate("document.querySelector('.insight-overview').textContent"), /已读取成员消息：135/)
    assert.match(await evaluate("document.querySelector('.insight-overview').textContent"), /120 \/ 120/)
    assert.equal(await evaluate("document.querySelectorAll('.mbti-axis meter').length"), 4)
    assert.equal(await evaluate("document.querySelector('.affinity-score') === null"), true)
    assert.match(await evaluate("document.querySelector('.portrait-hero').textContent"), /同名成员/)
    await checkLayout('member-a-light-1280')
    await setValue('[aria-label="画像分析对象"]', 'b')
    await wait("document.querySelector('.summary-card')?.textContent.includes('合成成员 b摘要')")
    assert.match(await outputText(), /成员读取 1/)
    result.checks.push('group_and_same_name_members_keep_valid_scoped_portraits')

    await click('[aria-label="画像分析设置"]')
    await wait("document.querySelector('.analysis-settings').open")
    await click('.start-analysis')
    await wait("document.querySelector('.insight-overview').textContent.includes('分析中')")
    for (const selector of ['[aria-label="画像分析对象"]', '[aria-label="选择分析对象"]', '[aria-label="画像分析历史"]']) assert.equal(await evaluate(`document.querySelector(${JSON.stringify(selector)}).disabled`), true)
    assert.match(await outputText(), /新建合成任务 1.*API 配置读取 0/)
    await click('.insight-overview button')
    await wait("document.querySelector('.insight-overview').textContent.includes('已取消')")
    await setValue('[aria-label="画像分析历史"]', 'saved-member-b')
    await wait("document.querySelector('.summary-card')?.textContent.includes('合成成员 b摘要')")
    await viewport(390)
    await checkLayout('member-settings-light-390')
    result.checks.push('explicit_start_cancel_and_restore_do_not_call_remote_models')

    await viewport(1280)
    await send('Page.navigate', { url: `${fixtureOrigin}/tests/fixtures/local-search.html?models&usage` })
    await wait("document.querySelectorAll('.ais-audit-table tbody tr').length === 3")
    await click('#ais-usage-tab')
    const totals = await evaluate("document.querySelector('.ais-metrics').textContent")
    assert.match(totals, /累计调用3次.*输入 tokens150.*输出 tokens25/)
    assert.equal(await evaluate("document.querySelector('.ais-audit-table tbody tr:last-child button').disabled"), true)
    await click('.ais-audit-table tbody tr:first-child button')
    await wait("document.querySelector('.ais-audit-confirm')")
    assert.match(await evaluate("document.querySelector('.ais-audit-confirm').textContent"), /累计用量、任务统计和聊天分析结果保留/)
    await capture('usage-delete-confirmation')
    await click('.ais-audit-confirm button:last-child')
    assert.equal(await evaluate("document.querySelectorAll('.ais-audit-table tbody tr').length"), 3)
    await click('.ais-audit-table tbody tr:first-child button')
    await click('.ais-audit-confirm button:first-child')
    await wait("document.querySelectorAll('.ais-audit-table tbody tr').length === 2")
    assert.equal(await evaluate("document.querySelector('.ais-metrics').textContent"), totals)
    await click('#ais-usage .ais-audit-toolbar button:last-child')
    await wait("document.querySelector('.ais-audit-confirm')")
    assert.match(await evaluate("document.querySelector('.ais-audit-confirm').textContent"), /所有账号.*运行中记录会保留/)
    await click('.ais-audit-confirm button:first-child')
    await wait("document.querySelectorAll('.ais-audit-table tbody tr').length === 1")
    assert.equal(await evaluate("document.querySelector('.ais-metrics').textContent"), totals)
    await click('#ais-usage .ais-audit-toolbar button:first-child')
    await wait("!document.querySelector('#ais-usage .ais-audit-toolbar button:first-child').disabled")
    assert.equal(await evaluate("document.querySelectorAll('.ais-audit-table tbody tr').length"), 1)
    await capture('usage-cleared-totals-retained')
    await click('.qa-toolbar button:first-of-type')
    await viewport(800)
    assert.equal(await evaluate("document.documentElement.scrollWidth > innerWidth"), false)
    await capture('usage-cleared-dark-narrow')
    result.checks.push('usage_single_bulk_cancel_refresh_preserve_totals_and_running_record')
    assert.deepEqual(result.blocked_requests, [])
    assert.deepEqual(result.errors, [])
    result.passed = true
  } catch (error) {
    result.passed = false; result.failure = error.stack; process.exitCode = 1
    if (socket?.readyState === 1) {
      const debug = await send('Runtime.evaluate', { expression: 'document.body.innerText', returnByValue: true })
      result.debug = debug.result.value
      const screenshot = await send('Page.captureScreenshot', { format: 'png' })
      await fs.writeFile(path.join(output, 'failure.png'), Buffer.from(screenshot.data, 'base64'))
    }
  } finally {
    await fs.writeFile(path.join(output, 'result.json'), JSON.stringify(result, null, 2))
    console.log(JSON.stringify(result, null, 2))
    if (socket?.readyState === 1) socket.close()
    child.kill()
  }
}
main().catch(error => { console.error(error); process.exitCode = 1 })
